test('buildUrl keeps query key insertion order with queryOrder "insertion"', () => {
  const url = buildUrl({
    baseUrl: 'https://api.example.test',
    path: ['items'],
    query: { z: 'last', a: 'first', m: 'mid' },
    queryOrder: 'insertion'
  });

  assert.equal(url, 'https://api.example.test/items?z=last&a=first&m=mid');
});

test('array items keep array order under both query orders', () => {
  const query = { tag: ['b', 'a', 'c'], alpha: 1 };

  assert.equal(
    _private.serializeQuery(query, 'sorted'),
    'alpha=1&tag=b&tag=a&tag=c'
  );
  assert.equal(
    _private.serializeQuery(query, 'insertion'),
    'tag=b&tag=a&tag=c&alpha=1'
  );
});

test('insertion order still omits null, undefined, and empty values but keeps 0 and false', () => {
  const url = buildUrl({
    baseUrl: 'https://api.example.test',
    query: { z: 0, y: null, x: false, w: '', v: undefined, u: 'kept' },
    queryOrder: 'insertion'
  });

  assert.equal(url, 'https://api.example.test/?z=0&x=false&u=kept');
});

test('URLSearchParams query is passed through unchanged under both query orders', () => {
  for (const queryOrder of ['sorted', 'insertion']) {
    const url = buildUrl({
      baseUrl: 'https://api.example.test',
      path: ['items'],
      query: new URLSearchParams([['b', '1'], ['a', '2']]),
      queryOrder
    });

    assert.equal(url, 'https://api.example.test/items?b=1&a=2');
  }
});

test('buildUrl throws TypeError for an unsupported queryOrder', () => {
  for (const queryOrder of ['reverse', 'Sorted', '', null, 0, false, true, {}, []]) {
    assert.throws(
      () => buildUrl({ baseUrl: 'https://api.example.test', query: { a: 1 }, queryOrder }),
      TypeError,
      `queryOrder ${JSON.stringify(queryOrder)} should throw`
    );
  }
});

test('buildUrl validates queryOrder even when the query is a URLSearchParams', () => {
  assert.throws(
    () => buildUrl({
      baseUrl: 'https://api.example.test',
      query: new URLSearchParams('a=1'),
      queryOrder: 'nope'
    }),
    TypeError
  );
});

test('buildSignedUrl passes queryOrder through to buildUrl', () => {
  const options = {
    baseUrl: 'https://api.example.test',
    path: 'items',
    query: { b: 1, a: 2 }
  };
  const sorted = buildSignedUrl(options, 'secret');
  const insertion = buildSignedUrl({ ...options, queryOrder: 'insertion' }, 'secret');

  assert.match(sorted, /\\/items\\?a=2&b=1&signature=[a-f0-9]{64}$/);
  assert.match(insertion, /\\/items\\?b=1&a=2&signature=[a-f0-9]{64}$/);
  assert.throws(() => buildSignedUrl({ ...options, queryOrder: 'bad' }, 'secret'), TypeError);
});

test('buildSignedUrl appends""",1)
open(p,'w').write(s)
